    @Tag("C3A_GATE_B") @ParameterizedTest @ValueSource(strings={"coordinator","run","attempt","stage"}) void changedOwnershipOrProcessEvidenceIsNeverAdopted(String change){occupied();var repo=new ControlRepository(jdbc,tx,INSTALL,ids->{switch(change){case "coordinator" ->jdbc.update("UPDATE ddip_management.coordinator SET row_version=row_version+1");case "run" ->jdbc.update("UPDATE ddip_management.runs SET row_version=row_version+1 WHERE run_id=?",run);case "attempt" ->jdbc.update("UPDATE ddip_management.attempts SET row_version=row_version+1 WHERE attempt_id=?",attempt);case "stage" ->liveStage();}});assertThatThrownBy(()->repo.request(command("changed"))).hasMessage(change.equals("run")?"PRECONDITION_FAILED":"STATE_CONFLICT");noControl();}
