    @Tag("C3A_GATE_B") @ParameterizedTest @ValueSource(strings={"same","different"}) void deterministicConcurrentAdmission(String keys)throws Exception {occupied();var barrier=new CyclicBarrier(2);var repo=new ControlRepository(jdbc,tx,INSTALL,ids->{try{barrier.await(10,TimeUnit.SECONDS);}catch(Exception ex){throw new IllegalStateException(ex);}ControlProcesses.check(ids);});
        try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->repo.request(command("first")).get("controlId").stringValue());var b=pool.submit(()->{try{return repo.request(command(keys.equals("same")?"first":"second")).get("controlId").stringValue();}catch(SourceFailure ex){return ex.code.name();}});String first;try{first=a.get(15,TimeUnit.SECONDS);}catch(ExecutionException ex){assertThat(ex.getCause()).hasMessage("STATE_CONFLICT");first="STATE_CONFLICT";}String second=b.get(15,TimeUnit.SECONDS);if(keys.equals("same"))assertThat(first).isEqualTo(second);else assertThat(List.of(first,second)).contains("STATE_CONFLICT");}assertThat(count("controls")).isEqualTo(1);assertThat(jdbc.queryForObject("SELECT count(*) FROM ddip_management.audit_events WHERE action='CONTROL_REQUESTED'",Long.class)).isEqualTo(1);
    }
