    JdbcTemplate lostAck(){var commits=new AtomicInteger();var ds=new AbstractDataSource(){public Connection getConnection()throws SQLException{var real=jdbc.getDataSource().getConnection();return(Connection)Proxy.newProxyInstance(getClass().getClassLoader(),new Class<?>[]{Connection.class},(p,m,args)->{try{Object r=m.invoke(real,args);if(m.getName().equals("commit") && commits.incrementAndGet()==2)throw new SQLException("PRIVATE","08006");return r;}catch(InvocationTargetException ex){throw ex.getCause();}});}public Connection getConnection(String u,String p)throws SQLException{return getConnection();}};return new JdbcTemplate(ds);}
