    @Tag("C3A_GATE_B") @Test void restartPersistsControlAndOriginalOccupiedOwner()throws Exception {occupied();var c=command("restart");var data=controls.request(c);String id=data.get("controlId").stringValue();var before=ownership();start();close();var started=jdbc.queryForObject("SELECT pg_postmaster_start_time()",OffsetDateTime.class);String signal=System.getProperty("ddip.test.control-restart-signal");if(signal!=null){Files.writeString(Path.of(signal),"READY");long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(45);while(!Files.exists(Path.of(signal+".done")) && System.nanoTime()<end)Thread.sleep(100);assertThat(Files.exists(Path.of(signal+".done"))).isTrue();assertThat(jdbc.queryForObject("SELECT pg_postmaster_start_time()",OffsetDateTime.class)).isAfter(started);}assertThat(body(http(get(path()+"/"+id))).get("data")).isEqualTo(data);assertThat(controls.request(c)).isEqualTo(data);assertThat(ownership()).isEqualTo(before);}
